//
// What the mock received of each kind of credential the client sends, and a call that needs none.

import assert from 'node:assert/strict'
import { after, before, test } from 'node:test'
import { Swagger } from "swagger-sdk"
import { mock } from '../mock/server.mjs'

let server
let client

before(async () => {
  server = await mock()
  client = new Swagger({ baseURL: server.url, basic: { username: 'user', password: 'pass' }, header: 'test-credential', query: 'test-credential', app: { clientId: 'test-client', clientSecret: 'test-secret', tokenURL: `${server.url}/oauth/token` }, maxRetries: 0 })
})

after(() => server.close())

/** The request the mock answered last; `null` against a server of your own. */
const last = () => server.requests?.at(-1) ?? null

test("basic: sent by pets.list", async () => {
  await client.pets.list()
  const r = last()
  if (r === null) return
  assert.equal(r.headers.authorization, `Basic ${Buffer.from('user:pass').toString('base64')}`)
})

test("header: sent by pets.add", async () => {
  await client.pets.add()
  const r = last()
  if (r === null) return
  assert.equal(r.headers["x-key"], 'test-credential')
})

test("app: sent by pets.mine", async () => {
  await client.pets.mine()
  const r = last()
  if (r === null) return
  assert.equal(r.headers.authorization, 'Bearer mock-token')
  assert.ok(server.requests.some((q) => q.route === 'token'), 'the token was requested of the mock')
})

test("no credential: health.get needs none", async () => {
  const none = new Swagger({ baseURL: server.url, maxRetries: 0, basic: null, header: null, query: null, app: null })
  await none.health.get()
  const r = last()
  if (r === null) return
  assert.equal(r.headers.authorization, undefined)
  assert.equal(r.headers["x-key"], undefined)
  assert.equal(new URL(r.url, 'http://mock.invalid').searchParams.has("key"), false)
})
